<?php
declare(strict_types=1);
function humanReviewCheck(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}
$root=dirname(__DIR__);
$settings=file_get_contents($root.'/model/FebOcrSettings.php');
humanReviewCheck(str_contains($settings,"'verification_mode' => 'ai'"),'AI must remain the safe default');
humanReviewCheck(str_contains($settings,"'human_reviewer_ids' => []"),'Reviewer selection must be persisted');
humanReviewCheck(str_contains($settings,"'allow_all'")&&str_contains($settings,'auto_accept_days')&&str_contains($settings,"Africa/Abidjan"),'Scheduled automatic acceptance must be persisted and use Abidjan time');
$form=file_get_contents($root.'/employe/nouvelle_demande_employe.php');
humanReviewCheck(str_contains($form,"febDocumentVerificationMode === 'human'"),'FEB form must route documents to human review');
humanReviewCheck(str_contains($form,'feb_human_review_token'),'FEB submission must carry a review token');
humanReviewCheck(str_contains($form,"['status'] ?? '') !== 'approved'"),'Server submission must require actual approval');
humanReviewCheck(str_contains($form,"if (\$submissionVerificationMode === 'ai' && \$febOcrEnabled && \$complianceDocument"),'Server must only call FIDEST IA in AI mode');
humanReviewCheck(str_contains($form,"febDocumentVerificationMode === 'allow_all'"),'Automatic acceptance must unlock the FEB form');
$documentEndpoint=file_get_contents($root.'/request/check_feb_document_fidest_ia.php');
humanReviewCheck(str_contains($documentEndpoint,"if (\$activeMode !== 'ai')"),'FIDEST IA endpoint must bypass OCR outside AI mode');
$service=file_get_contents($root.'/services/FebHumanDocumentReviewService.php');
humanReviewCheck(str_contains($service,"r.status='pending'"),'Only pending reviews may be decided');
humanReviewCheck(str_contains($service,"in_array(\$decision,['approved','rejected']"),'Review decisions must be constrained');
humanReviewCheck(str_contains($service,"\$decision==='rejected'&&trim(\$reason)===''"),'A rejection reason must be mandatory');
humanReviewCheck(str_contains($service,'ensureSchema()'),'Human review schema must self-initialize after deployment');
humanReviewCheck(str_contains($service,"'sub_key'=>'review_'.\$id"),'Each review notification must carry a distinct key');
humanReviewCheck(str_contains($service,'new NotificationRepository($this->pdo)'),'System notification tables must be available before submission');
humanReviewCheck(str_contains($service,'employee_chat_messages(sender_user_id,recipient_user_id,body,created_at)'),'Reviewers must receive a direct chat reminder');
humanReviewCheck(str_contains($service,'https://projet.fidest.ci/validation_justificatifs_feb.php?review='),'Chat reminder must include a clickable review link');
$reviewPage=file_get_contents($root.'/validation_justificatifs_feb.php');
humanReviewCheck(str_contains($reviewPage,'<article id="review-'),'Pending reviews must render as individual cards');
humanReviewCheck(str_contains($reviewPage,'<iframe src=')&&str_contains($reviewPage,'<img src='),'Documents must be previewable on the card');
humanReviewCheck(str_contains($reviewPage,'<details class=')&&str_contains($reviewPage,'Détails de la demande et du devis'),'Review cards must show an expandable request summary');
humanReviewCheck(str_contains($reviewPage,"\$line['libelle']")&&str_contains($reviewPage,"\$line['quantite']")&&str_contains($reviewPage,"\$line['prix_unitaire']"),'The request summary must show quote lines and prices');
humanReviewCheck(str_contains($reviewPage,'request/export_feb_human_review_quote_pdf.php?id='),'Quote button must target the FINEA PDF, not the uploaded proof');
$quotePdf=file_get_contents($root.'/request/export_feb_human_review_quote_pdf.php');
$quoteBuilder=file_get_contents($root.'/services/FebHumanReviewQuotePdfBuilder.php');
humanReviewCheck(str_contains($quoteBuilder,'CompanyPdfTemplate')&&str_contains($quoteBuilder,'companyPdfQrPayload'),'Quote PDF must use the ISO 9001 Banamur template and QR code');
humanReviewCheck(str_contains($quoteBuilder,'infoCard(')&&str_contains($quoteBuilder,'tableRow(')&&str_contains($quoteBuilder,'TOTAL DÉCLARÉ DANS LA DEMANDE'),'Quote PDF body must use dedicated information cards, table rows and a total block');
humanReviewCheck(str_contains($quotePdf,'fileFor($reviewId, $userId)'),'Quote PDF access must be limited to assigned reviewers');
$migration=file_get_contents($root.'/database/migrations/20260921_create_feb_human_document_reviews.sql');
humanReviewCheck(str_contains($migration,'UNIQUE KEY uq_feb_human_review_token'),'Review tokens must be unique');
echo "FebHumanDocumentReviewTest: OK\n";
